\editiostamp{2026-09-05}{}

\claimV{The synthetic Northbridge pilot records coefficient \editionum{current-coefficient} from run NB-42 after contaminant control, with raw-output checksum 7f3c.}\editiogrounds{finding-20260905T002329Z-northbridge-run-validates-coefficient-seventeen} \claimV{The recorded publication rule requires retaining that checksum when reporting the coefficient.}\editiogrounds{finding-20260905T002329Z-checksum-gates-northbridge-calibration-publication}

